SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET CHARACTER SET utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";

-- ΔΙΑΓΡΑΦΗ ΔΕΔΟΜΕΝΩΝ
SET @reset_table_exists = (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'timesheets');
SET @reset_sql = IF(@reset_table_exists > 0, 'DELETE FROM `timesheets`', 'SELECT 1');
PREPARE reset_stmt FROM @reset_sql;
EXECUTE reset_stmt;
DEALLOCATE PREPARE reset_stmt;
SET @reset_sql = IF(@reset_table_exists > 0, 'ALTER TABLE `timesheets` AUTO_INCREMENT = 1', 'SELECT 1');
PREPARE reset_stmt FROM @reset_sql;
EXECUTE reset_stmt;
DEALLOCATE PREPARE reset_stmt;
